"use client";

import { Badge } from "@repo/design-system/components/ui/badge";
import { cn } from "@repo/design-system/lib/utils";
import type {
  AgentStatus,
  Harness,
  SessionStatus,
  Tone,
} from "../types";

const sessionStatusConfig: Record<
  SessionStatus,
  { label: string; tone: Tone; pulse?: boolean }
> = {
  active: { label: "Active", tone: "success", pulse: true },
  waiting: { label: "Waiting", tone: "accent", pulse: true },
  completed: { label: "Completed", tone: "muted" },
  error: { label: "Error", tone: "danger" },
  abandoned: { label: "Abandoned", tone: "warning" },
};

const agentStatusConfig: Record<
  AgentStatus,
  { label: string; tone: Tone; pulse?: boolean }
> = {
  working: { label: "Working", tone: "success", pulse: true },
  waiting: { label: "Waiting", tone: "accent", pulse: true },
  completed: { label: "Completed", tone: "muted" },
  error: { label: "Error", tone: "danger" },
  idle: { label: "Idle", tone: "default" },
};

const toneClasses: Record<Tone, string> = {
  default: "border-input-border bg-input text-foreground",
  success: "border-success/25 bg-success/12 text-success",
  warning: "border-warning/30 bg-warning/14 text-warning-foreground",
  danger: "border-destructive/25 bg-destructive/12 text-destructive",
  info: "border-info/25 bg-info/12 text-info",
  accent: "border-primary/20 bg-primary/10 text-primary",
  muted: "border-border bg-muted/70 text-muted-foreground",
};

const harnessConfig: Record<string, { label: string; tone: Tone }> = {
  claude: { label: "Claude", tone: "accent" },
  codex: { label: "Codex", tone: "info" },
  cursor: { label: "Cursor", tone: "warning" },
  copilot: { label: "Copilot", tone: "success" },
  opencode: { label: "OpenCode", tone: "danger" },
};

function resolveSessionStatusConfig(
  status: SessionStatus | string
): { label: string; tone: Tone; pulse?: boolean } {
  if (status in sessionStatusConfig) {
    return sessionStatusConfig[status as SessionStatus];
  }

  if (status === "failed") {
    return { label: "Failed", tone: "danger" };
  }

  return {
    label: status.replace(/[-_]/g, " "),
    tone: "danger",
  };
}

function resolveAgentStatusConfig(
  status: AgentStatus | string
): { label: string; tone: Tone; pulse?: boolean } {
  if (status in agentStatusConfig) {
    return agentStatusConfig[status as AgentStatus];
  }

  if (status === "failed") {
    return { label: "Failed", tone: "danger" };
  }

  return {
    label: status.replace(/[-_]/g, " "),
    tone: "danger",
  };
}

type ToneBadgeProps = {
  label: string;
  tone?: Tone;
  pulse?: boolean;
  className?: string;
};

export function ToneBadge({
  label,
  tone = "default",
  pulse = false,
  className,
}: ToneBadgeProps) {
  return (
    <Badge
      className={cn(
        "h-6 gap-1.5 rounded-full px-2.5 font-semibold text-[11px] tracking-[0.01em]",
        toneClasses[tone],
        className
      )}
      variant="outline"
    >
      <span
        aria-hidden="true"
        className={cn(
          "size-1.5 rounded-full bg-current",
          pulse && "animate-[pulse_1.6s_ease-in-out_infinite]"
        )}
      />
      {label}
    </Badge>
  );
}

export function SessionStatusBadge({
  status,
}: {
  status: SessionStatus | string;
}) {
  const config = resolveSessionStatusConfig(status);
  return (
    <ToneBadge
      label={config.label}
      pulse={config.pulse}
      tone={config.tone}
    />
  );
}

export function AgentStatusBadge({
  status,
}: {
  status: AgentStatus | string;
}) {
  const config = resolveAgentStatusConfig(status);
  return (
    <ToneBadge
      label={config.label}
      pulse={config.pulse}
      tone={config.tone}
    />
  );
}

export function HarnessBadge({
  harness,
}: {
  harness?: Harness | null;
}) {
  const config = harnessConfig[(harness || "claude").toLowerCase()] || {
    label: harness || "Claude",
    tone: "accent" as const,
  };

  return <ToneBadge label={config.label} tone={config.tone} />;
}
